function fmtVND(n){return new Intl.NumberFormat("vi-VN").format(Math.round(n||0))+" ₫";}
function fmtC(n){if(!n)return"0";if(n>=1e6)return(n/1e6).toFixed(3).replace(/\.?0+$/,"")+"M";return Math.round(n/1e3)+"k";}
function today(){return new Date().toLocaleDateString("vi-VN",{day:"2-digit",month:"2-digit",year:"numeric"});}
function dateAfter(d){const dt=new Date();dt.setDate(dt.getDate()+d);return dt.toLocaleDateString("vi-VN",{day:"2-digit",month:"2-digit",year:"numeric"});}
function newQID(){const n=new Date();return"BG-"+n.getFullYear()+String(n.getMonth()+1).padStart(2,"0")+String(n.getDate()).padStart(2,"0")+"-"+String(Math.floor(Math.random()*900)+100);}

function buildPrompt(co,qid){
  let cat="";
  D.s.forEach(s=>{
    const vt=s.vi?"(VAT đã gộp)":"(VAT "+s.v+"% chưa gộp)";
    cat+="\n### "+s.n+" ("+s.p.length+" SP) "+vt+"\n";
    if(s.notes&&s.notes.length)s.notes.slice(0,3).forEach(nt=>{cat+="  📌 "+nt+"\n";});
    s.p.forEach(p=>{
      const id=(p.c?p.c+" | ":"")+((p.n||"").substring(0,80));
      cat+="• "+id+(p.x?" ["+p.x+"]":"")+"\n";
      if(p.t&&p.t.length)cat+="  Giá: "+p.t.map(t=>t.l+":"+fmtC(t.p)).join(" | ")+"\n";
    });
  });
  const q=qid||newQID();
  const tmpl='{"quoteNumber":"'+q+'","date":"'+today()+'","validUntil":"'+dateAfter(30)+'","customer":{"name":"","address":"","phone":""},"items":[{"stt":1,"code":"","name":"","unit":"Cái","quantity":0,"unitPrice":0,"amount":0,"tierUsed":""}],"subtotal":0,"vatRate":0,"vatIncluded":false,"vatAmount":0,"total":0,"notes":""}';
  return "Bạn là trợ lý tạo báo giá cho "+(co&&co.name?co.name:"Quà Tặng VIVA")+".\n\n## DANH MỤC"+cat+"\n## QUY TẮC BÁO GIÁ\n1. PHẢI HỎI SỐ LƯỢNG trước khi báo giá nếu chưa có — không thể chọn đúng bậc giá\n2. CHỌN ĐÚNG BẬC: 75 cái→50-100; 200 cái→200-300; 600 cái→501-1000\n3. VAT: xem theo từng sheet (đã gộp hay chưa)\n4. Tính: amount=qty×price; vat=sub×vatRate/100; total=sub+vat\n5. Tìm SP bằng mã hoặc tên gần đúng\n\n## FORMAT JSON BÁO GIÁ (bắt buộc khi đủ thông tin)\nQUOTE_JSON_START\n"+tmpl+"\nQUOTE_JSON_END\nSau JSON: 1-2 câu tóm tắt tiếng Việt.";
}

function CatalogModal({onClose}){
  const[tab,setTab]=useState(0);
  const[q,setQ]=useState("");
  const s=D.s[tab];
  const prods=(s?s.p:[]).filter(p=>!q||JSON.stringify(p).toLowerCase().includes(q.toLowerCase()));
  return(
    <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,.72)",zIndex:999,display:"flex",alignItems:"center",justifyContent:"center",padding:"16px"}} onClick={onClose}>
      <div style={{background:"#0f2035",border:"1px solid rgba(255,255,255,.1)",borderRadius:"16px",width:"100%",maxWidth:"900px",maxHeight:"88vh",overflow:"hidden",display:"flex",flexDirection:"column",fontFamily:"'Plus Jakarta Sans',sans-serif"}} onClick={e=>e.stopPropagation()}>
        <div style={{padding:"12px 17px",borderBottom:"1px solid rgba(255,255,255,.08)",display:"flex",alignItems:"center",gap:"10px"}}>
          <span style={{color:"#FAFAF8",fontWeight:"700",fontSize:"14px",flex:1}}>📦 {D.s.reduce((n,sh)=>n+sh.p.length,0)} sản phẩm · {D.s.length} nhóm</span>
          <input value={q} onChange={e=>setQ(e.target.value)} placeholder="🔍 Tìm kiếm..." style={{background:"rgba(255,255,255,.07)",border:"1px solid rgba(255,255,255,.1)",borderRadius:"8px",padding:"6px 12px",color:"#FAFAF8",fontSize:"12px",fontFamily:"inherit",outline:"none",width:"200px"}}/>
          <button onClick={onClose} style={{background:"rgba(255,255,255,.06)",border:"none",borderRadius:"6px",padding:"5px 12px",color:"rgba(255,255,255,.4)",cursor:"pointer",fontSize:"12px"}}>✕</button>
        </div>
        <div style={{display:"flex",gap:"2px",padding:"7px 13px",borderBottom:"1px solid rgba(255,255,255,.07)",overflowX:"auto",flexShrink:0}}>
          {D.s.map((sh,i)=>(
            <button key={i} onClick={()=>{setTab(i);setQ("");}} style={{padding:"4px 11px",border:"none",borderRadius:"6px",fontFamily:"inherit",whiteSpace:"nowrap",background:i===tab?"rgba(196,146,42,.2)":"rgba(255,255,255,.04)",color:i===tab?"#C4922A":"rgba(255,255,255,.35)",fontWeight:"600",fontSize:"11px",cursor:"pointer"}}>
              {sh.n.length>14?sh.n.substring(0,14)+"…":sh.n} <span style={{opacity:.5}}>({sh.p.length})</span>
            </button>
          ))}
        </div>
        {s&&<div style={{padding:"5px 17px",background:"rgba(196,146,42,.06)",borderBottom:"1px solid rgba(196,146,42,.1)",fontSize:"11px",color:"rgba(196,146,42,.75)",flexShrink:0}}>
          VAT {s.v}% {s.vi?"(đã gộp)":"(chưa gộp)"}{s.tl&&s.tl.length>0?" · Bậc giá: "+s.tl.slice(0,4).join(" | "):""}
        </div>}
        <div style={{overflowY:"auto",flex:1}}>
          <table style={{width:"100%",borderCollapse:"collapse",fontSize:"12px"}}>
            <thead style={{position:"sticky",top:0,background:"#0f2035",zIndex:1}}>
              <tr>
                {["Mã SP","Tên sản phẩm"].concat((s&&s.tl?s.tl:[]).slice(0,4)).map((h,i)=>(
                  <th key={i} style={{padding:"7px 11px",textAlign:i>=2?"right":"left",color:i>=2?"rgba(196,146,42,.6)":"rgba(255,255,255,.38)",fontWeight:"700",fontSize:"10px",letterSpacing:".06em",textTransform:"uppercase",borderBottom:"1px solid rgba(255,255,255,.08)",whiteSpace:"nowrap"}}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {prods.slice(0,100).map((p,idx)=>(
                <tr key={idx} style={{borderBottom:"1px solid rgba(255,255,255,.04)"}}>
                  <td style={{padding:"7px 11px",color:"#C4922A",fontFamily:"monospace",fontSize:"11px",whiteSpace:"nowrap"}}>{p.c||"—"}</td>
                  <td style={{padding:"7px 11px",color:"rgba(255,255,255,.65)",maxWidth:"260px",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{p.n||"—"}</td>
                  {(s&&s.tl?s.tl:[]).slice(0,4).map((tl,j)=>{
                    const tier=p.t&&p.t.find(t=>t.l===tl);
                    return <td key={j} style={{padding:"7px 11px",textAlign:"right",color:tier?"rgba(255,255,255,.78)":"rgba(255,255,255,.18)",fontFamily:"monospace",fontSize:"11px"}}>{tier?fmtVND(tier.p):"—"}</td>;
                  })}
                </tr>
              ))}
            </tbody>
          </table>
          {prods.length===0&&<div style={{padding:"32px",color:"rgba(255,255,255,.25)",textAlign:"center",fontSize:"13px"}}>Không tìm thấy</div>}
          {prods.length>100&&<div style={{padding:"10px",color:"rgba(255,255,255,.25)",textAlign:"center",fontSize:"11px"}}>Hiển thị 100/{prods.length} · Dùng tìm kiếm để lọc</div>}
        </div>
      </div>
    </div>
  );
}

function Settings({co,setCo,onClose}){
  const INP={background:"rgba(255,255,255,.08)",border:"1px solid rgba(255,255,255,.13)",borderRadius:"8px",padding:"8px 12px",color:"#FAFAF8",fontSize:"13px",fontFamily:"inherit",outline:"none",width:"100%"};
  const flds=[["name","Tên công ty","1/-1"],["address","Địa chỉ","1/-1"],["phone","Điện thoại",""],["email","Email",""],["tax","Mã số thuế",""],["bankName","Ngân hàng",""],["bank","Số tài khoản","1/-1"]];
  return(
    <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,.65)",zIndex:998,display:"flex",alignItems:"center",justifyContent:"flex-end"}} onClick={onClose}>
      <div style={{background:"#0f2035",width:"360px",height:"100%",overflowY:"auto",padding:"24px",fontFamily:"'Plus Jakarta Sans',sans-serif",boxShadow:"-8px 0 32px rgba(0,0,0,.4)"}} onClick={e=>e.stopPropagation()}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:"20px"}}>
          <span style={{color:"#FAFAF8",fontWeight:"700",fontSize:"15px"}}>⚙ Thông tin công ty</span>
          <button onClick={onClose} style={{background:"rgba(255,255,255,.06)",border:"none",borderRadius:"6px",padding:"5px 10px",color:"rgba(255,255,255,.5)",cursor:"pointer"}}>✕</button>
        </div>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:"10px"}}>
          {flds.map(([k,lbl,span])=>(
            <div key={k} style={{display:"flex",flexDirection:"column",gap:"4px",gridColumn:span||undefined}}>
              <label style={{color:"rgba(255,255,255,.3)",fontSize:"10px",fontWeight:"700",letterSpacing:".06em",textTransform:"uppercase"}}>{lbl}</label>
              <input style={INP} value={co[k]||""} onChange={e=>setCo(p=>({...p,[k]:e.target.value}))}/>
            </div>
          ))}
        </div>
        <button onClick={onClose} style={{marginTop:"20px",width:"100%",padding:"11px",borderRadius:"9px",border:"none",background:"linear-gradient(135deg,#C4922A,#E8B84B)",color:"#09182a",fontSize:"14px",fontWeight:"700",cursor:"pointer",fontFamily:"inherit"}}>Lưu →</button>
      </div>
    </div>
  );
}

